// Verification gate: accept the alert only if it is complete and consistent.
const body = $input.first().json.body || {};
const ids = Array.isArray(body.track_ids) ? body.track_ids : [];
const reasons = [];

if (!body.image_base64) reasons.push('image missing');
if (typeof body.count !== 'number') reasons.push('count missing');
if (body.alert_type === 'zone_occupancy') {
  // deterministic ByteTrack count: the count must be exactly the list of IDs
  if (body.count !== ids.length) reasons.push(`count ${body.count} != ${ids.length} track_ids`);
  if (body.count < body.threshold) reasons.push('count below threshold');
  if ((body.sustained_frames || 0) < (body.sustain_required_frames || 1)) reasons.push('rule not sustained');
} else if (body.alert_type === 'stockout') {
  if (body.count >= body.threshold) reasons.push('stock is not below the minimum');
} else {
  reasons.push(`unknown alert_type: ${body.alert_type}`);
}

const verified = reasons.length === 0;
const fileName = `${body.alert_type || 'alert'}_${String(body.timestamp || Date.now()).replace(/[^0-9]/g, '').slice(0, 17)}.jpg`;
const message = body.alert_type === 'stockout'
  ? `Rupture de stock - ${body.zone} : ${body.count} produit(s), minimum ${body.threshold}`
  : `Affluence - ${body.zone} : ${body.count} personnes (IDs ${ids.join(', ')}), seuil ${body.threshold}, maintenu ${body.sustained_frames} images`;

const item = {
  json: {
    verified, reasons, message, file_name: fileName,
    alert_type: body.alert_type, zone: body.zone, count: body.count, track_ids: ids,
    timestamp: body.timestamp, image_sha256: body.image_sha256,
  },
};
if (body.image_base64) {
  const buffer = Buffer.from(body.image_base64, 'base64');
  try {
    item.binary = { image: await this.helpers.prepareBinaryData(buffer, fileName, 'image/jpeg') };
  } catch (e) {
    item.binary = { image: { data: body.image_base64, mimeType: 'image/jpeg', fileName, fileExtension: 'jpg' } };
  }
}
return [item];
